cd /tmp && python3 - <<'EOF'
from jinja2 import Environment, DictLoader, FunctionLoader, PrefixLoader, ChoiceLoader, BaseLoader, TemplateNotFound
from jinja2.loaders import split_template_path

# DictLoader
d = DictLoader({"b.html": "B{{v}}", "a.html": "A"})
env = Environment(loader=d)
print("dict:", env.get_template("b.html").render(v=1), env.list_templates())
s,f,u = d.get_source(env, "a.html"); print("dict tuple:", repr(s), f, u())
try: d.get_source(env,"x")
except TemplateNotFound: print("dict notfound ok")

# FunctionLoader: str, tuple, None
def lf(name):
    if name == "s": return "STR{{v}}"
    if name == "t": return ("TUP", "fn.html", lambda: False)
    return None
fl = FunctionLoader(lf); env = Environment(loader=fl)
print("func str:", env.get_template("s").render(v=2))
print("func tuple:", fl.get_source(env, "t"))
print("func tuple render:", env.get_template("t").render())
try: fl.get_source(env, "z")
except TemplateNotFound: print("func notfound ok")
try: fl.list_templates()
except TypeError as e: print("func list_templates TypeError ok:", e)

# PrefixLoader
pl = PrefixLoader({"a": DictLoader({"t": "a-t"}), "b": DictLoader({"t": "b-t"})})
env = Environment(loader=pl)
print("prefix:", env.get_template("a/t").render(), env.get_template("b/t").render())
print("prefix list:", sorted(pl.list_templates()))
print("get_loader:", pl.get_loader("a/t")[1])
try: env.get_template("a/missing")
except TemplateNotFound as e: print("prefix notfound name:", e.name)
try: env.get_template("nodelim")
except TemplateNotFound as e: print("prefix nodelim:", e.name)
pl2 = PrefixLoader({"a": DictLoader({"t":"AT"})}, delimiter="::")
print("delim:", Environment(loader=pl2).get_template("a::t").render())

# ChoiceLoader
cl = ChoiceLoader([DictLoader({"x":"first"}), DictLoader({"x":"second","y":"only2"})])
env = Environment(loader=cl)
print("choice:", env.get_template("x").render(), env.get_template("y").render(), cl.list_templates())
try: env.get_template("zz")
except TemplateNotFound as e: print("choice notfound:", e.name)

# BaseLoader
b = BaseLoader()
try: b.get_source(Environment(), "t")
except TemplateNotFound: print("base get_source notfound ok")
try: b.list_templates()
except TypeError as e: print("base list_templates ok:", e)
class NoAccess(BaseLoader):
    has_source_access = False
try: NoAccess().get_source(Environment(), "t")
except RuntimeError as e: print("no-access RuntimeError ok:", e)

# split_template_path
print(split_template_path("foo/bar"), split_template_path("./a//b/./c"))
for bad in ["../a", "a/../b", "foo/..", "a\\b" ]:
    try: print(bad, "->", split_template_path(bad))
    except TemplateNotFound: print(bad, "-> TemplateNotFound")
EOF

